// Items from Data Dragon (generated by tools/build_items.py). Only base items are offered on level up; each extra copy
// of a base evolves one owned item of its line one step along a fixed path (LINES), up to a unique finished item.
import data from './items.json';

export interface ItemStats {
  ad?: number; as?: number; hp?: number; mana?: number; crit?: number; armor?: number; msPct?: number;
  lifesteal?: number; omnivamp?: number; ah?: number; armorPen?: number; critDamage?: number;
}
export interface Item {
  id: string;
  name: string;
  stats: ItemStats;
}

export const ITEMS = data.items as Record<string, Item>;
export const MAX_ITEMS = 6;
export const itemIcon = (id: string) => `https://ddragon.leagueoflegends.com/cdn/${data.version}/img/item/${id}.png`;

// Passive descriptions and effects: src/itemEffects.ts

/** Evolution paths per base item (steps after the base). Copies needed for a path = its length + 1. */
export const LINES: Record<string, string[][]> = {
  '1036': [ // Espada Longa
    ['1037', '1038', '1018', '3031'], ['1037', '1053', '3153'],
    ['3044', '3067', '3071'], ['3044', '3051', '3078'],
    ['3133', '3035', '6694'], ['3133', '2517'],
    ['2021', '3161'],
    ['6670', '3051', '6672'],
  ],
  '1042': [ // Adaga
    ['1043', '3086', '6672'], ['1043', '1053', '3153'],
    ['3051', '3044', '3078'],
    ['3086', '6670', '1038', '3031'],
    ['3144', '3086', '3085'],
  ],
  '2022': [ // Partícula Brilhante
    ['3057', '3044', '3078'], ['3057', '1018', '3508'],
    ['3067', '3044', '3071'],
    ['3133', '3004'],
  ],
  '1028': [['3044', '3067', '3071'], ['2021', '3161'], ['6660', '1031', '3068']], // Cristal de Rubi
  '1029': [['3082', '3110'], ['2019', '1038', '3026'], ['1031', '6660', '3068']], // Couraça de Pano
  '3070': [['1027', '3004'], ['3024', '3110']], // Lágrima da Deusa
  '1018': [['3057', '3133', '3508'], ['6670', '1038', '1037', '3031'], ['3086', '3144', '3085']], // Capa da Agilidade
};
export const BASES = Object.keys(LINES);

/** An inventory slot: its line and the steps taken so far (empty = still the base item). */
export interface Slot { base: string; path: string[] }
export const slotItem = (s: Slot) => s.path.at(-1) ?? s.base;
const startsWith = (p: string[], prefix: string[]) => prefix.every((id, i) => p[i] === id);
const pathsOf = (s: Slot) => LINES[s.base].filter((p) => startsWith(p, s.path));
export const isFinal = (s: Slot) => pathsOf(s).some((p) => p.length === s.path.length);
const finalsOf = (s: Slot) => new Set(pathsOf(s).map((p) => p.at(-1)!));

/** Finished items owned or reserved (every remaining path of a slot ends in them) by slots other than `skip`. */
export function claimed(slots: Slot[], skip = -1) {
  const out = new Set<string>();
  slots.forEach((s, i) => {
    const f = finalsOf(s);
    if (i !== skip && f.size === 1) out.add([...f][0]);
  });
  return out;
}

/** Next steps open to slot i: branches with at least one path whose finished item is not claimed elsewhere. */
export function nextSteps(slots: Slot[], i: number) {
  const s = slots[i];
  const taken = claimed(slots, i);
  return [...new Set(pathsOf(s).filter((p) => p.length > s.path.length && !taken.has(p.at(-1)!)).map((p) => p[s.path.length]))];
}
/** Finished items reachable from slot i if it takes `step` next. */
export function finalsVia(slots: Slot[], i: number, step: string) {
  const s = slots[i];
  const taken = claimed(slots, i);
  return [...new Set(pathsOf({ ...s, path: [...s.path, step] }).map((p) => p.at(-1)!).filter((f) => !taken.has(f)))];
}
export const isLocked = (slots: Slot[], i: number) => !isFinal(slots[i]) && !nextSteps(slots, i).length;
export const buildComplete = (slots: Slot[]) =>
  slots.length === MAX_ITEMS && slots.every((s, i) => isFinal(s) || isLocked(slots, i));

/** Random distinct bases; with a full inventory only bases that can evolve an owned item. */
export function rollOffers(slots: Slot[], count = 3): string[] {
  const pool = slots.length < MAX_ITEMS ? [...BASES]
    : BASES.filter((b) => slots.some((s, i) => s.base === b && nextSteps(slots, i).length));
  const out: string[] = [];
  while (out.length < count && pool.length) out.push(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  return out;
}

/** Path tree of a line, for the UI: each node keeps the steps that lead to it. */
export interface LineNode { id: string; path: string[]; kids: LineNode[] }
export function lineTree(base: string): LineNode {
  const node = (id: string, path: string[]): LineNode => {
    const next = [...new Set(LINES[base].filter((p) => p.length > path.length && startsWith(p, path)).map((p) => p[path.length]))];
    return { id, path, kids: next.map((n) => node(n, [...path, n])) };
  };
  return node(base, []);
}

export const POTION = { hp: 0.2, mana: 0.2 }; // fraction of max HP / mana restored by the build-complete potions
export const LEGENDARY_BONUS = 0.5; // blueprint: +50% of the item's stats
export const BLUEPRINT_CHANCE = 0.01; // per kill, once the build is complete

/** Stats of the current items; `legendary` is the slot upgraded by the blueprint (-1 for none). */
export function sumStats(inventory: string[], legendary = -1): Required<ItemStats> {
  const s: Required<ItemStats> = {
    ad: 0, as: 0, hp: 0, mana: 0, crit: 0, armor: 0, msPct: 0, lifesteal: 0, omnivamp: 0, ah: 0, armorPen: 0, critDamage: 0,
  };
  inventory.forEach((id, slot) => {
    const mult = slot === legendary ? 1 + LEGENDARY_BONUS : 1;
    for (const [k, raw] of Object.entries(ITEMS[id].stats)) {
      const v = raw * mult;
      // armor penetration doesn't stack additively in LoL; keep the best source
      if (k === 'armorPen') s.armorPen = Math.max(s.armorPen, v);
      else s[k as keyof ItemStats] += v;
    }
  });
  return s;
}

const STAT_LABEL: Record<keyof ItemStats, (v: number) => string> = {
  ad: (v) => `+${Math.round(v)} DdA`, as: (v) => `+${Math.round(v * 100)}% Vel. Ataque`, hp: (v) => `+${Math.round(v)} Vida`, mana: (v) => `+${Math.round(v)} Mana`,
  crit: (v) => `+${Math.round(v * 100)}% Crítico`, armor: (v) => `+${Math.round(v)} Armadura`, msPct: (v) => `+${Math.round(v * 100)}% Vel. Movimento`,
  lifesteal: (v) => `+${Math.round(v * 100)}% Roubo de Vida`, omnivamp: (v) => `+${Math.round(v * 100)}% Vampirismo`,
  ah: (v) => `+${Math.round(v)} Acel. Habilidade`, armorPen: (v) => `+${Math.round(v * 100)}% Pen. Armadura`,
  critDamage: (v) => `+${Math.round(v * 100)}% Dano Crítico`,
};
export const describeStats = (s: ItemStats, mult = 1) =>
  Object.entries(s).map(([k, v]) => STAT_LABEL[k as keyof ItemStats](v * mult)).join(' · ');
